import { studio } from './app.js';
import { empty, validate, letters, melodic, defaultAttributes } from './project.js';
import { midiName, prepareSamples, cachedSample } from './audio.js';
import { openLibrary, getRecord, listProjects, deleteProject, saveWorking } from './storage.js';
const ui=s=>document.querySelector(s),CELL=44,ROW=22,TOP=84,BOTTOM=24;
let workspace='compose',rollOn=false,boxMode=false,noteSelection=new Set(),noteClipboard=null,rollContext='',gesture=null,libraryDb=null,activeProjectId=null,libraryGeneration=0;
const samplePeaks=new WeakMap();
const offlineDecoder=()=>new (window.OfflineAudioContext||window.webkitOfflineAudioContext)(1,1,44100);
function chooseWorkspace(view){if(view==='compose'&&rollOn&&!melodic(studio.project.tracks[studio.selected]))studio.select(6,0);workspace=view;document.querySelectorAll('[data-workspace]').forEach(n=>n.classList.toggle('workspace-hidden',n.dataset.workspace!==view));document.querySelectorAll('[data-view]').forEach(n=>n.setAttribute('aria-pressed',n.dataset.view===view));ui('.creation-rack').classList.toggle('workspace-hidden',!['compose','mix'].includes(view));if(view==='library')renderLibrary();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>chooseWorkspace(b.dataset.view));
function chooseEditor(piano){rollOn=piano;if(piano&&!melodic(studio.project.tracks[studio.selected]))studio.select(6,0);ui('#piano-panel').hidden=!piano;ui('.sequence-panel').hidden=piano;ui('#step-view').classList.toggle('selected',!piano);ui('#piano-view').classList.toggle('selected',piano);renderStage();if(piano)centerRoll();}
ui('#step-view').onclick=()=>chooseEditor(false);ui('#piano-view').onclick=()=>chooseEditor(true);
for(let n=24;n<=84;n++){ui('#step-pitch').add(new Option(midiName(n),String(n)));ui('#sample-root').add(new Option(midiName(n),String(n)));}
ui('#roll-track').onchange=e=>{studio.select(Number(e.target.value),0);centerRoll();};
studio.project.tracks.forEach((t,i)=>ui('#mix-track').add(new Option(t.name,String(i))));
ui('#mix-track').onchange=e=>studio.select(Number(e.target.value),0);
function currentAttributes(){return studio.project.patterns[studio.project.pattern].attributes[studio.selected];}
function selectedSteps(){return rollOn&&noteSelection.size?[...noteSelection]:[studio.step];}
function renderStage(){
 const p=studio.project,t=p.tracks[studio.selected],step=studio.step,a=currentAttributes()[step];
 ui('#mix-track').value=studio.selected;ui('#current-project-label').textContent=p.name;ui('#project-name').value=p.name;
 ui('#step-title').textContent=`${t.name} · ${letters[p.pattern]} / 第 ${step+1} 步${rollOn&&noteSelection.size>1?' · 已选 '+noteSelection.size+' 个音符':''}`;
 ui('#note-enabled').checked=t.steps[step]!==null;ui('#step-pitch').disabled=!melodic(t);ui('#step-pitch').value=t.steps[step]??(studio.selected===6?36:60)+p.root;
 ui('#step-duration').innerHTML=Array.from({length:16-step},(_,i)=>`<option value="${i+1}">${i+1} 步${i===3?' / 1 拍':''}</option>`).join('');ui('#step-duration').value=a.duration;ui('#step-duration').disabled=!melodic(t);
 ui('#step-ratchet').value=a.ratchet;ui('#step-velocity').value=a.velocity;ui('#velocity-value').value=a.velocity+'%';ui('#step-probability').value=a.probability;ui('#probability-value').value=a.probability+'%';
 document.querySelectorAll('.step').forEach(b=>{const attr=p.patterns[p.pattern].attributes[Number(b.dataset.track)][Number(b.dataset.step)];b.style.setProperty('--velocity',.3+attr.velocity*.007);b.classList.toggle('accent',attr.ratchet>1);b.title=`力度 ${attr.velocity}% · 概率 ${attr.probability}% · 连击 ${attr.ratchet} 次`;});
 renderSample();
 const context=p.pattern+':'+studio.selected;if(context!==rollContext){noteSelection=new Set(t.steps[step]===null?[]:[step]);rollContext=context;}
 noteSelection=new Set([...noteSelection].filter(s=>t.steps[s]!==null));if(rollOn){ui('#roll-track').value=melodic(t)?studio.selected:6;renderRoll();}
}
ui('#note-enabled').onchange=e=>studio.mutate(()=>{const t=studio.project.tracks[studio.selected];t.steps[studio.step]=e.target.checked?(melodic(t)?Number(ui('#step-pitch').value):60):null;});
ui('#step-pitch').onchange=e=>studio.mutate(()=>{for(const s of selectedSteps())studio.project.tracks[studio.selected].steps[s]=Number(e.target.value);});
for(const [control,prop] of [['velocity','velocity'],['probability','probability'],['ratchet','ratchet'],['duration','duration']]){
 ui('#step-'+control).addEventListener(control==='velocity'||control==='probability'?'input':'change',e=>{const value=Number(e.target.value);studio.mutate(()=>{for(const s of selectedSteps())currentAttributes()[s][prop]=prop==='duration'?Math.min(value,16-s):value;},'attribute-'+prop+'-'+studio.selected+'-'+studio.step);});
}
ui('#step-audition').onclick=async()=>{try{await studio.engine.init();const t=studio.project.tracks[studio.selected];await studio.engine.audition(t,t.steps[studio.step]??Number(ui('#step-pitch').value),currentAttributes()[studio.step]);}catch(e){studio.toast(e.message);}};
const keys=Array.from({length:TOP-BOTTOM+1},(_,i)=>{const pitch=TOP-i;return `<span class="piano-key ${[1,3,6,8,10].includes(pitch%12)?'black-key':''}">${midiName(pitch)}</span>`;}).join('');ui('#roll-keys').innerHTML=keys;
ui('#roll-surface').style.height=(TOP-BOTTOM+1)*ROW+'px';
function renderRoll(){const t=studio.project.tracks[studio.selected],attrs=currentAttributes();ui('#roll-notes').innerHTML=t.steps.map((pitch,s)=>pitch===null?'':`<div class="roll-note ${noteSelection.has(s)?'selected':''}" role="button" aria-label="${midiName(pitch)} 第 ${s+1} 步，时值 ${attrs[s].duration} 步" data-roll-note="${s}" style="left:${s*CELL+2}px;top:${(TOP-pitch)*ROW+2}px;width:${attrs[s].duration*CELL-4}px;opacity:${.4+attrs[s].velocity*.006}"><span>${midiName(pitch)}</span><i class="note-handle" data-resize="${s}"></i></div>`).join('');}
function centerRoll(){const row=studio.project.tracks[studio.selected].steps.find(n=>n!==null)??(studio.selected===6?36:60);ui('#roll-scroll').scrollTop=Math.max(0,(TOP-row)*ROW-110);}
function point(e){const r=ui('#roll-surface').getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
ui('#box-mode').onclick=()=>{boxMode=!boxMode;ui('#box-mode').setAttribute('aria-pressed',boxMode);ui('#box-mode').classList.toggle('on',boxMode);};
const surface=ui('#roll-surface');
surface.onpointerdown=e=>{
 if(e.button!==0)return;surface.focus();const pos=point(e),note=e.target.closest('[data-roll-note]');
 if(note){const s=Number(note.dataset.rollNote);if(e.shiftKey&&noteSelection.has(s)){noteSelection.delete(s);renderRoll();return;}if(!noteSelection.has(s)){if(!e.shiftKey)noteSelection.clear();noteSelection.add(s);}studio.select(studio.selected,s);gesture={kind:e.target.closest('[data-resize]')?'resize':'move',start:pos,step:s,original:[...noteSelection].map(n=>({step:n,pitch:studio.project.tracks[studio.selected].steps[n],attr:{...currentAttributes()[n]}})),dx:0,dy:0};}
 else{gesture={kind:'blank',start:pos,end:pos,moved:false};if(!e.shiftKey)noteSelection.clear();}
 surface.setPointerCapture(e.pointerId);e.preventDefault();
};
surface.onpointermove=e=>{if(!gesture)return;const pos=point(e);if(gesture.kind==='blank'){gesture.end=pos;gesture.moved=Math.hypot(pos.x-gesture.start.x,pos.y-gesture.start.y)>5;const box=ui('#roll-box');box.hidden=!(boxMode||gesture.moved);Object.assign(box.style,{left:Math.min(pos.x,gesture.start.x)+'px',top:Math.min(pos.y,gesture.start.y)+'px',width:Math.abs(pos.x-gesture.start.x)+'px',height:Math.abs(pos.y-gesture.start.y)+'px'});return;}
 let dx=Math.round((pos.x-gesture.start.x)/CELL),dy=-Math.round((pos.y-gesture.start.y)/ROW);
 if(gesture.kind==='move'){dx=Math.max(-Math.min(...gesture.original.map(n=>n.step)),Math.min(15-Math.max(...gesture.original.map(n=>n.step)),dx));dy=Math.max(BOTTOM-Math.min(...gesture.original.map(n=>n.pitch)),Math.min(TOP-Math.max(...gesture.original.map(n=>n.pitch)),dy));for(const n of gesture.original){const b=ui(`[data-roll-note="${n.step}"]`);if(b)b.style.transform=`translate(${dx*CELL}px,${-dy*ROW}px)`;}}
 else{const n=gesture.original.find(n=>n.step===gesture.step),duration=Math.max(1,Math.min(16-n.step,n.attr.duration+dx));const b=ui(`[data-roll-note="${n.step}"]`);b.style.width=duration*CELL-4+'px';dx=duration-n.attr.duration;dy=0;}
 gesture.dx=dx;gesture.dy=dy;
};
surface.onpointerup=e=>{
 if(!gesture)return;const g=gesture;gesture=null;ui('#roll-box').hidden=true;
 if(g.kind==='blank'){
  if(g.moved||boxMode){const x1=Math.min(g.start.x,g.end.x),x2=Math.max(g.start.x,g.end.x),y1=Math.min(g.start.y,g.end.y),y2=Math.max(g.start.y,g.end.y);studio.project.tracks[studio.selected].steps.forEach((pitch,s)=>{if(pitch===null)return;const y=(TOP-pitch)*ROW;if(s*CELL<x2&&(s+currentAttributes()[s].duration)*CELL>x1&&y<y2&&y+ROW>y1)noteSelection.add(s);});renderRoll();renderStage();return;}
  const s=Math.min(15,Math.max(0,Math.floor(g.start.x/CELL))),pitch=Math.min(TOP,Math.max(BOTTOM,TOP-Math.floor(g.start.y/ROW)));noteSelection=new Set([s]);studio.mutate(()=>{studio.project.tracks[studio.selected].steps[s]=pitch;currentAttributes()[s]=defaultAttributes();});studio.select(studio.selected,s);return;
 }
 if(!g.dx&&!g.dy){renderRoll();return;}
 if(g.kind==='resize'){studio.mutate(()=>currentAttributes()[g.step].duration+=g.dx);return;}
 studio.mutate(()=>{const row=studio.project.tracks[studio.selected].steps,attrs=currentAttributes();for(const n of g.original){row[n.step]=null;attrs[n.step]=defaultAttributes();}for(const n of g.original){const target=n.step+g.dx;row[target]=n.pitch+g.dy;attrs[target]={...n.attr,duration:Math.min(n.attr.duration,16-target)};}noteSelection=new Set(g.original.map(n=>n.step+g.dx));});studio.select(studio.selected,g.step+g.dx);
};
surface.onpointercancel=()=>{gesture=null;ui('#roll-box').hidden=true;renderRoll();};
function copyNotes(){const steps=[...noteSelection].sort((a,b)=>a-b);if(!steps.length){studio.toast('先选择音符');return;}const base=steps[0];noteClipboard=steps.map(s=>({offset:s-base,pitch:studio.project.tracks[studio.selected].steps[s],attr:{...currentAttributes()[s]}}));studio.toast(`已复制 ${steps.length} 个音符，将从选中步粘贴`);}
function pasteNotes(){if(!noteClipboard){studio.toast('先复制音符');return;}const base=studio.step;studio.mutate(()=>{noteSelection.clear();for(const n of noteClipboard){const s=base+n.offset;if(s>=16)continue;studio.project.tracks[studio.selected].steps[s]=n.pitch;currentAttributes()[s]={...n.attr,duration:Math.min(n.attr.duration,16-s)};noteSelection.add(s);}});}
function transposeNotes(delta){if(!noteSelection.size)return;studio.mutate(()=>{const row=studio.project.tracks[studio.selected].steps;for(const s of noteSelection)row[s]=Math.max(BOTTOM,Math.min(TOP,row[s]+delta));});}
function deleteNotes(){if(!noteSelection.size)return;studio.mutate(()=>{for(const s of noteSelection){studio.project.tracks[studio.selected].steps[s]=null;currentAttributes()[s]=defaultAttributes();}noteSelection.clear();});}
ui('#roll-copy').onclick=copyNotes;ui('#roll-paste').onclick=pasteNotes;ui('#transpose-up').onclick=()=>transposeNotes(1);ui('#transpose-down').onclick=()=>transposeNotes(-1);ui('#roll-delete').onclick=deleteNotes;
surface.onkeydown=e=>{if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='a'){e.preventDefault();noteSelection=new Set(studio.project.tracks[studio.selected].steps.map((n,i)=>n===null?null:i).filter(n=>n!==null));renderRoll();renderStage();}if(e.key.toLowerCase()==='c'){e.preventDefault();copyNotes();}if(e.key.toLowerCase()==='v'){e.preventDefault();pasteNotes();}return;}if(['Delete','Backspace'].includes(e.key)){e.preventDefault();deleteNotes();}if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();transposeNotes(e.key==='ArrowUp'?1:-1);}};
function renderSample(){const p=studio.project,t=p.tracks[studio.selected],s=t.sample;ui('#sample-name').textContent=s?p.samples[s.id].name:'使用内置合成音色';ui('#sample-settings').hidden=!s;ui('#sample-wave').hidden=!s;if(!s)return;ui('#sample-start').value=s.start*100;ui('#sample-end').value=s.end*100;ui('#sample-start-value').value=(s.start*100).toFixed(1)+'%';ui('#sample-end-value').value=(s.end*100).toFixed(1)+'%';ui('#sample-root').value=s.root;ui('#sample-reverse').setAttribute('aria-pressed',s.reverse);ui('#sample-reverse').classList.toggle('on',s.reverse);const buffer=cachedSample(s.id);if(!buffer)return;const canvas=ui('#sample-wave'),g=canvas.getContext('2d'),data=buffer.getChannelData(0);g.clearRect(0,0,440,100);g.fillStyle='#84d5c522';g.fillRect(s.start*440,0,(s.end-s.start)*440,100);g.strokeStyle='#84d5c5';g.beginPath();if(!samplePeaks.has(buffer)){const peaks=new Float32Array(440);for(let x=0;x<440;x++){const begin=Math.floor(x/440*data.length),end=Math.floor((x+1)/440*data.length);for(let i=begin;i<end;i++)peaks[x]=Math.max(peaks[x],Math.abs(data[i]));}samplePeaks.set(buffer,peaks);}const peaks=samplePeaks.get(buffer);for(let x=0;x<440;x++){g.moveTo(x,50-peaks[x]*45);g.lineTo(x,50+peaks[x]*45);}g.stroke();g.strokeStyle='#ff955b';for(const x of [s.start*440,s.end*440]){g.beginPath();g.moveTo(x,0);g.lineTo(x,100);g.stroke();}}
ui('#import-sample').onclick=()=>ui('#sample-file').click();
ui('#sample-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const button=ui('#import-sample'),trackIndex=studio.selected,targetProject=studio.project,rack=ui('.instrument');button.disabled=true;rack.inert=true;document.body.classList.add('loading');ui('#loading-state').textContent='正在解码采样…';ui('#loading-state').hidden=false;try{if(file.size>8*1024*1024)throw new Error('单个采样最多 8 MB');const bytes=new Uint8Array(await file.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=16384)text+=String.fromCharCode(...bytes.subarray(i,i+16384));const data=btoa(text),id='sample-'+crypto.randomUUID(),sample={name:file.name.slice(0,120),mime:file.type||'audio/wav',data},p=targetProject;const keep=new Set(p.tracks.filter((t,i)=>i!==trackIndex&&t.sample).map(t=>t.sample.id));const newSamples={...Object.fromEntries(Object.entries(p.samples).filter(([id])=>keep.has(id))),[id]:sample};if(Object.values(newSamples).reduce((n,s)=>n+s.data.length,0)>34000000)throw new Error('工程采样总量最多 24 MB');await prepareSamples({samples:newSamples},offlineDecoder());if(studio.project!==targetProject)throw new Error('工程已切换，请重新导入采样');studio.engine.pause(true);studio.mutate(()=>{studio.project.samples=newSamples;studio.project.tracks[trackIndex].sample={id,start:0,end:1,reverse:false,root:trackIndex===6?36:60};});studio.toast('采样已载入该声部，并随工程保存');}catch(err){studio.toast(err.message);}finally{button.disabled=false;rack.inert=false;document.body.classList.remove('loading');ui('#loading-state').hidden=true;e.target.value='';}};
for(const prop of ['start','end'])ui('#sample-'+prop).oninput=e=>{const v=Number(e.target.value)/100;studio.mutate(()=>{const s=studio.project.tracks[studio.selected].sample;if(prop==='start')s.start=Math.min(v,s.end-.005);else s.end=Math.max(v,s.start+.005);},'sample-'+prop+'-'+studio.selected);};
ui('#sample-root').onchange=e=>studio.mutate(()=>studio.project.tracks[studio.selected].sample.root=Number(e.target.value));
ui('#sample-reverse').onclick=()=>studio.mutate(()=>{const s=studio.project.tracks[studio.selected].sample;s.reverse=!s.reverse;});
ui('#remove-sample').onclick=()=>studio.mutate(()=>{studio.project.tracks[studio.selected].sample=null;const keep=new Set(studio.project.tracks.filter(t=>t.sample).map(t=>t.sample.id));studio.project.samples=Object.fromEntries(Object.entries(studio.project.samples).filter(([id])=>keep.has(id)));});
async function renderLibrary(){if(!libraryDb)return;const generation=++libraryGeneration,projects=await listProjects(libraryDb);if(generation!==libraryGeneration)return;ui('#library-status').textContent=`${projects.length} 个作品 · 当前设备`;const list=ui('#library-list');list.replaceChildren();if(!projects.length){const n=document.createElement('p');n.className='secondary';n.textContent='还没有作品。给当前工程命名并保存，或导入已有工程。';list.append(n);return;}for(const item of projects){const card=document.createElement('article');card.className='project-card'+(item.id===activeProjectId?' current-project':'');const title=document.createElement('h3');title.textContent=item.name;const meta=document.createElement('p');meta.className='secondary';meta.textContent=`${item.project.bpm} BPM · ${Object.keys(item.project.samples||{}).length} 个采样 · ${new Date(item.updatedAt).toLocaleString('zh-CN')}`;const buttons=document.createElement('div');const open=document.createElement('button');open.className='outline-btn';open.textContent=item.id===activeProjectId?'当前作品':'打开';open.disabled=item.id===activeProjectId;open.onclick=async()=>{try{if(!await studio.flush())throw new Error('当前工程保存失败，请先导出备份');const latest=await getRecord(libraryDb,'projects',item.id);if(!latest)throw new Error('作品已删除');const p=validate(latest.project);await prepareSamples(p,offlineDecoder());activeProjectId=item.id;studio.load(p);await studio.save();studio.toast('作品已打开');}catch(e){studio.toast(e.message);}};const remove=document.createElement('button');remove.className='text-btn';remove.textContent='删除';remove.onclick=async()=>{if(!confirm(`从当前设备删除「${item.name}」？`))return;try{await deleteProject(libraryDb,item.id);if(activeProjectId===item.id)activeProjectId=null;await renderLibrary();}catch(e){studio.toast('删除失败，请重试');}};buttons.append(open,remove);card.append(title,meta,buttons);list.append(card);}}
// Naming stays in the form until the user chooses save or save a copy.
async function saveNamed(copy=false){if(!libraryDb){studio.toast('当前设备的工程库不可用，请导出工程');return;}const name=ui('#project-name').value.trim()||'Untitled Groove';if(copy&&!await studio.flush())return;studio.mutate(()=>studio.project.name=name);if(copy||!activeProjectId)activeProjectId='project-'+crypto.randomUUID();if(await studio.flush()){studio.toast(copy?'副本已保存':'作品已保存');await renderLibrary();}}
ui('#library-save').onclick=()=>saveNamed();ui('#library-copy').onclick=()=>saveNamed(true);
ui('#new-project').onclick=async()=>{if(!await studio.flush())return;if(!activeProjectId&&!confirm('当前未命名工程会保留在自动备份中。新建空白工程？'))return;activeProjectId=null;studio.load(empty());await studio.save();studio.toast('已新建空白工程');chooseWorkspace('compose');chooseEditor(false);};
ui('#recover-backup').onclick=async()=>{if(!libraryDb)return;try{const backup=await getRecord(libraryDb,'state','backup');if(!backup){studio.toast('暂无自动备份');return;}const p=validate(backup.project);await prepareSamples(p,offlineDecoder());if(!confirm(`恢复「${p.name}」的上一份自动备份？当前内容可通过撤销恢复。`))return;studio.replace(p);studio.toast('已恢复上次自动备份');}catch(e){studio.toast('无法恢复备份：'+e.message);}};
studio.subscribe(renderStage);chooseWorkspace('compose');renderStage();
async function boot(){let recovered=false;try{libraryDb=await openLibrary();const [working,backup,active]=await Promise.all([getRecord(libraryDb,'state','working'),getRecord(libraryDb,'state','backup'),getRecord(libraryDb,'state','activeId')]);activeProjectId=active||null;if(working){try{const p=validate(working.project);await prepareSamples(p,offlineDecoder());studio.load(p);}catch(e){if(backup){const p=validate(backup.project);await prepareSamples(p,offlineDecoder());studio.load(p);recovered=true;studio.toast('当前工程异常，已恢复上一份自动备份');}else{throw e;}}}studio.setPersistence(async p=>{await saveWorking(libraryDb,p,activeProjectId,recovered);recovered=false;if(workspace==='library')await renderLibrary();});await studio.save();await renderLibrary();}catch(e){libraryDb=null;ui('#library-status').textContent='工程库不可用，请导出工程备份';studio.toast('本地载入失败：'+e.message);}finally{document.body.classList.remove('loading');ui('#loading-state').hidden=true;renderStage();}}
await boot();
